mapper.select:
select id from order_event_outbox
where next_retry_at <= #{now}
  and (status = 'PENDING' or (status = 'PROCESSING' and locked_until <= #{now}))
order by next_retry_at, id
limit #{limit}

mapper.update:
update order_event_outbox
set status = 'PROCESSING', locked_until = #{lockedUntil}, lock_token = #{lockToken},
    update_time = #{now}
where id = #{id} and next_retry_at <= #{now}
  and (status = 'PENDING' or (status = 'PROCESSING' and locked_until <= #{now}))

update order_event_outbox
set status = 'PROCESSED', processed_at = #{now}, locked_until = null,
    lock_token = null, last_error = null, update_time = #{now}
where id = #{id} and status = 'PROCESSING' and lock_token = #{lockToken}

update order_event_outbox
set status = 'PENDING', retry_count = #{retryCount}, next_retry_at = #{nextRetryAt},
    locked_until = null, lock_token = null, last_error = #{lastError}, update_time = #{now}
where id = #{id} and status = 'PROCESSING' and lock_token = #{lockToken}

update order_event_outbox
set status = 'DEAD', retry_count = #{retryCount}, locked_until = null,
    lock_token = null, last_error = #{lastError}, update_time = #{now}
where id = #{id} and status = 'PROCESSING' and lock_token = #{lockToken}

mapper.select:
select * from order_event_outbox

    and status = #{status}
    and event_type = #{eventType}

order by create_time desc, id desc
